import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CPP_SOURCE = r"""
#include <torch/extension.h>

torch::Tensor min_reduce_cuda(torch::Tensor x, int64_t dim);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("min_reduce", &min_reduce_cuda, "CUDA min reduction");
}
"""


_CUDA_SOURCE = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>
#include <vector>

__global__ void min_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t d0,
    int64_t d1,
    int64_t d2,
    int64_t dim,
    int64_t output_numel,
    int64_t reduce_size
) {
    constexpr int warps_per_block = 8;
    const int lane = threadIdx.x & 31;
    const int warp_id = threadIdx.x >> 5;
    const unsigned mask = 0xffffffffu;
    const int64_t outputs_per_grid =
        static_cast<int64_t>(gridDim.x) * warps_per_block;
    for (int64_t output_index =
             static_cast<int64_t>(blockIdx.x) * warps_per_block + warp_id;
         output_index < output_numel;
         output_index += outputs_per_grid) {
        float local_min = INFINITY;
        int has_nan = 0;
        int64_t base_offset;
        int64_t reduce_stride;
        if (dim == 0) {
            const int64_t i1 = output_index / d2;
            const int64_t i2 = output_index % d2;
            base_offset = i1 * d2 + i2;
            reduce_stride = d1 * d2;
        } else if (dim == 1) {
            const int64_t i0 = output_index / d2;
            const int64_t i2 = output_index % d2;
            base_offset = i0 * d1 * d2 + i2;
            reduce_stride = d2;
        } else {
            base_offset = output_index;
            reduce_stride = 1;
        }
        for (int64_t r = lane; r < reduce_size; r += 32) {
            const float value = x[base_offset + r * reduce_stride];
            if (isnan(value)) {
                has_nan = 1;
            } else if (value < local_min) {
                local_min = value;
            }
        }
        for (int offset = 16; offset > 0; offset >>= 1) {
            const float other_min = __shfl_down_sync(mask, local_min, offset);
            const int other_nan = __shfl_down_sync(mask, has_nan, offset);
            if (other_nan) {
                has_nan = 1;
            } else if (!has_nan && other_min < local_min) {
                local_min = other_min;
            }
        }
        if (lane == 0) {
            out[output_index] = has_nan ? NAN : local_min;
        }
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::ScalarType::Float,
                "input must have dtype torch.float32");
    TORCH_CHECK(x.dim() == 3, "input must be a 3D tensor");
    TORCH_CHECK(x.is_contiguous(), "input must be contiguous");

    if (dim < 0) {
        dim += 3;
    }

    TORCH_CHECK(dim >= 0 && dim < 3, "reduction dimension must be 0, 1, or 2");

    const int64_t d0 = x.size(0);
    const int64_t d1 = x.size(1);
    const int64_t d2 = x.size(2);

    const int64_t reduce_size =
        dim == 0 ? d0 : (dim == 1 ? d1 : d2);

    TORCH_CHECK(reduce_size > 0, "cannot reduce an empty dimension");

    std::vector<int64_t> output_sizes;
    if (dim == 0) {
        output_sizes = {d1, d2};
    } else if (dim == 1) {
        output_sizes = {d0, d2};
    } else {
        output_sizes = {d0, d1};
    }

    auto output = torch::empty(output_sizes, x.options());
    const int64_t output_numel = output.numel();

    constexpr int threads = 256;
    cudaDeviceProp prop;
    TORCH_CHECK(cudaGetDeviceProperties(&prop, x.get_device()) == cudaSuccess,
                "failed to query CUDA device properties");
    const int blocks_per_sm = std::max(1, prop.maxThreadsPerMultiProcessor / threads);
    const int target_blocks = 2 * prop.multiProcessorCount * blocks_per_sm;
    const int blocks = static_cast<int>(
        std::min<int64_t>(output_numel, std::max(1, target_blocks))
    );

    const auto stream = c10::cuda::getCurrentCUDAStream(x.get_device());

    min_reduce_kernel<<<blocks, threads, 0, stream.stream()>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        d0,
        d1,
        d2,
        dim,
        output_numel,
        reduce_size
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""


_min_reduce_cuda = load_inline(
    name="min_reduce_cuda_extension",
    cpp_sources=[_CPP_SOURCE],
    cuda_sources=[_CUDA_SOURCE],
    functions=None,
    with_cuda=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _min_reduce_cuda.min_reduce(x, self.dim)

